mapper.select:
SELECT COUNT(*)
  FROM stock_hold WITH (NOLOCK)
 WHERE lot_no = #{lotNo}
   AND reason_code = #{reason}
   AND released_at IS NULL

mapper.update:
UPDATE stock_hold
   SET released_at = #{releasedAt}, released_by = #{releasedBy}, release_comment = #{comment}
 WHERE lot_no = #{lotNo}
   AND released_at IS NULL
